import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]
    q_idx = 1 + 2 * N
    Q = data[q_idx]
    queries = data[q_idx + 1 : q_idx + 1 + Q]
    M = max(queries)

    size = 1
    while size < M:
        size <<= 1
    log = size.bit_length() - 1

    d = [-10**9] * (2 * size)
    lz = [0] * size

    for i in range(M):
        d[size + i] = i + 1
    for i in range(size - 1, 0, -1):
        d[i] = max(d[2 * i], d[2 * i + 1])

    def all_apply(k, f):
        d[k] += f
        if k < size:
            lz[k] += f

    def push(k):
        if lz[k]:
            f = lz[k]
            all_apply(2 * k, f)
            all_apply(2 * k + 1, f)
            lz[k] = 0

    def update(k):
        d[k] = max(d[2 * k], d[2 * k + 1])

    def range_add(l, r, f=1):
        if l >= r:
            return
        l += size
        r += size
        l2, r2 = l, r

        for i in range(log, 0, -1):
            if ((l >> i) << i) != l:
                push(l >> i)
            if ((r >> i) << i) != r:
                push((r - 1) >> i)

        while l < r:
            if l & 1:
                all_apply(l, f)
                l += 1
            if r & 1:
                r -= 1
                all_apply(r, f)
            l >>= 1
            r >>= 1

        l, r = l2, r2
        for i in range(1, log + 1):
            if ((l >> i) << i) != l:
                update(l >> i)
            if ((r >> i) << i) != r:
                update((r - 1) >> i)

    def find_first(target):
        if d[1] < target:
            return M
        k = 1
        while k < size:
            push(k)
            if d[2 * k] >= target:
                k = 2 * k
            else:
                k = 2 * k + 1
        idx = k - size
        if idx >= M:
            return M
        return idx

    for i in range(N):
        L = data[1 + 2 * i]
        R = data[2 + 2 * i]
        l = find_first(L)
        r = find_first(R + 1)
        if l < r:
            range_add(l, r, 1)

    for k in range(1, size):
        push(k)

    out = []
    for x in queries:
        out.append(str(d[size + x - 1]))
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
