import sys

def possible(A, require_non_alt):
    N = len(A)
    for x0 in (0, 1):
        # dp[prev_x][has_equal]
        dp = [[False, False] for _ in range(2)]
        dp[x0][0] = True
        for i in range(1, N):
            new_dp = [[False, False] for _ in range(2)]
            ai = A[i]
            for prev in (0, 1):
                for he in (0, 1):
                    if not dp[prev][he]:
                        continue
                    for curr in (0, 1):
                        if ai == 0:
                            if (prev ^ curr) != 1:
                                continue
                        else:
                            if prev == 1 and curr == 1:
                                continue
                        new_he = he or (prev == curr)
                        new_dp[curr][new_he] = True
            dp = new_dp

        for xN in (0, 1):
            for he in (0, 1):
                if not dp[xN][he]:
                    continue
                if A[0] == 0:
                    if (xN ^ x0) != 1:
                        continue
                else:
                    if xN == 1 and x0 == 1:
                        continue
                final_he = he or (xN == x0)
                if require_non_alt:
                    if final_he:
                        return True
                else:
                    return True
    return False


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    A = list(map(int, data[1:1 + N]))
    require_non_alt = (N % 4 == 2)
    ans = possible(A, require_non_alt)
    print("Yes" if ans else "No")


if __name__ == "__main__":
    main()
