import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    N = data[0]
    P = data[1:1 + N]

    bit = [0] * (N + 1)
    for i in range(1, N + 1):
        bit[i] = i & -i

    def find_kth(k):
        idx = 0
        step = 1 << (N.bit_length() - 1)
        while step:
            nxt = idx + step
            if nxt <= N and bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]
            step >>= 1
        return idx + 1

    def add(pos, delta):
        while pos <= N:
            bit[pos] += delta
            pos += pos & -pos

    ans = [0] * (N + 1)

    for i in range(N, 0, -1):
        pos = find_kth(P[i - 1])
        ans[pos] = i
        add(pos, -1)

    sys.stdout.write(" ".join(map(str, ans[1:])))

if __name__ == "__main__":
    main()
